-- ----------------------------
-- Table structure for operation_account
-- ----------------------------
DROP TABLE IF EXISTS "public"."operation_account";
CREATE TABLE "public"."operation_account" (
  "created_at" timestamptz(6) NOT NULL DEFAULT now(),
  "encrypted_secret" text COLLATE "pg_catalog"."default" NOT NULL,
  "group_id" uuid NOT NULL,
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "identifier" text COLLATE "pg_catalog"."default" NOT NULL,
  "name" text COLLATE "pg_catalog"."default" NOT NULL,
  "note" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::text,
  "status" "public"."operation_account_status" NOT NULL DEFAULT 'ready'::operation_account_status,
  "tags" text[] COLLATE "pg_catalog"."default" NOT NULL DEFAULT '{}'::text[],
  "updated_at" timestamptz(6) NOT NULL DEFAULT now(),
  "app" "public"."operation_account_app",
  "avatar" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::text,
  "backup_key" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::text,
  "backup_slot" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::text,
  "backup_type" "public"."operation_account_backup_type",
  "deleted" bool NOT NULL DEFAULT false,
  "deleted_at" timestamptz(6),
  "device_id" uuid,
  "device_instance_id" uuid,
  "encrypted_totp" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::text,
  "encrypted_transfer_key" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::text,
  "extra" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "favorite" int8,
  "follower" int8,
  "following" int8,
  "online" bool NOT NULL DEFAULT false,
  "platform_uid" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::text,
  "proxy_id" uuid,
  "region" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::text,
  "transferred" bool NOT NULL DEFAULT false
)
;
COMMENT ON COLUMN "public"."operation_account"."created_at" IS '创建或备份时间';
COMMENT ON COLUMN "public"."operation_account"."encrypted_secret" IS '平台密码密文，API 不回说明文';
COMMENT ON COLUMN "public"."operation_account"."group_id" IS '所属访问分组，对应原站 user_id 数据范围';
COMMENT ON COLUMN "public"."operation_account"."id" IS '主键 UUID';
COMMENT ON COLUMN "public"."operation_account"."identifier" IS '平台登录名 / unique_id，组内唯一';
COMMENT ON COLUMN "public"."operation_account"."name" IS '展示名，可默认等于用户名或 UID';
COMMENT ON COLUMN "public"."operation_account"."note" IS '备注';
COMMENT ON COLUMN "public"."operation_account"."status" IS 'ready 正常 / suspended 暂停 / disabled 封号';
COMMENT ON COLUMN "public"."operation_account"."tags" IS '业务分组与多标签，约定「收藏」表示已收藏';
COMMENT ON COLUMN "public"."operation_account"."updated_at" IS '资料最近更新时间';
COMMENT ON COLUMN "public"."operation_account"."app" IS '来源应用：tiktok / youtube / facebook / instagram / twitter';
COMMENT ON COLUMN "public"."operation_account"."avatar" IS '头像地址';
COMMENT ON COLUMN "public"."operation_account"."backup_key" IS '备份包在存储里的键';
COMMENT ON COLUMN "public"."operation_account"."backup_slot" IS '备份插槽名';
COMMENT ON COLUMN "public"."operation_account"."backup_type" IS 'local 本地 / private_cloud 私有云';
COMMENT ON COLUMN "public"."operation_account"."deleted" IS '是否在回收站';
COMMENT ON COLUMN "public"."operation_account"."deleted_at" IS '进回收站时间';
COMMENT ON COLUMN "public"."operation_account"."device_id" IS '备份来源盒子';
COMMENT ON COLUMN "public"."operation_account"."device_instance_id" IS '备份来源机位';
COMMENT ON COLUMN "public"."operation_account"."encrypted_totp" IS '2FA 密钥密文，空表示未开';
COMMENT ON COLUMN "public"."operation_account"."encrypted_transfer_key" IS '转移码密文';
COMMENT ON COLUMN "public"."operation_account"."extra" IS '签名、最近作品、最近任务等运行时数据';
COMMENT ON COLUMN "public"."operation_account"."favorite" IS '获赞或收藏数';
COMMENT ON COLUMN "public"."operation_account"."follower" IS '粉丝数，无平台同步时允许空';
COMMENT ON COLUMN "public"."operation_account"."following" IS '关注数';
COMMENT ON COLUMN "public"."operation_account"."online" IS '绑定机位是否在线，由设备健康或绑定时回写';
COMMENT ON COLUMN "public"."operation_account"."platform_uid" IS '平台数字 ID';
COMMENT ON COLUMN "public"."operation_account"."proxy_id" IS '绑定出口代理，代理删除后置空';
COMMENT ON COLUMN "public"."operation_account"."region" IS '账号归属地';
COMMENT ON COLUMN "public"."operation_account"."transferred" IS '是否已经转出';
COMMENT ON TABLE "public"."operation_account" IS '运营账号库：机位备份下来的社交账号，按 access_group 隔离，删除先进回收站';

